const partnerCount=ref(1),relationRows=computed(()=>build.relationTiers.map(r=>({name:`${r.min}·${r.name}`,...relationshipBonuses(Object.fromEntries(Array.from({length:partnerCount.value},(_,i)=>[i,r.min])))})))
