const endings=[{id:'guardian',mark:'b_guardian',title:'守护之心',meaning:'守护同伴与大陆，成为大家的依靠。'},{id:'brave',mark:'b_companion',title:'无畏的勇者',meaning:'勇于迎战，把经历带回学院。'},{id:'wise',mark:'b_wisdom',title:'大陆的智者',meaning:'记录知识，让后来者少走弯路。'},{id:'free',mark:'b_own_path',title:'自由的风',meaning:'选择自己的道路，继续认识世界。'}]
const coverageRows=FEATURE_COVERAGE.map(([name,status,scope,domain])=>({name,status,scope,domain}))
const fixes=[{tag:'01 / 经济循环',title:'经验丹套利封堵',trigger:'100级，或90级八环且门槛经验库存饱和。',before:'300金买经验，再从经验折金中赚回更多金币。',after:'100级/当前魂环等级上限拒绝购买，先校验后扣款。',proof:'覆盖满级、卡环、99级正常购买、金币不足、拒绝后余额不变。'},{tag:'02 / 构筑兑现',title:'影分身从配置走到战斗',trigger:'已学影分身，普通攻击后敌人仍存活。',before:'配置15%追击，但战斗没有读取该加成。',after:'15%判定，最多一次等额追击；不重复消耗、回合与奖励。',proof:'覆盖手动/自动、触发/未触发、零概率、击杀不追击和胜场只计一次。'},{tag:'03 / 时间一致',title:'旅行天数与世界时钟统一',trigger:'普通旅行显示10天，1天定义8时段。',before:'只推进1时段，与显示天数不符。',after:'推进80时段；事件数仍每趟+1，区分时间与行动。',proof:'覆盖普通、快速、首次请求快速回退，失败不扣款/不改位置。'}]
fixes.push({tag:'04 / 一次性奖励',title:'第六环淬炼不再重复发奖',trigger:'60级选择暂缓吸收，保留猎环目标后再次进入。',before:'每次可领取经验与永久属性；正常淬炼被显示成吸收反噬。',after:'每周目只奖励一次；保留吸收入口，准确说明暂缓突破。',proof:'回归验证首次发奖、第二次资源状态完全不变、目标仍保留及正确文案。'})
fixes.push({tag:'05 / 成功结算边界',title:'吸收失败不再领取成功奖励',trigger:'第九环非战斗吸收失败，尚未获得魂环。',before:'失败仍奖励选项经验与永久属性，可在卡环时大量折金。',after:'失败只结算反噬与行动，成功后才发该选项奖励；一次性淬炼单独处理。',proof:'真实样本发现异常金币峰值；回归覆盖失败资源不增、成功授环、重复请求不再发奖。'})
function format(v){return Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:2})}
function percent(v){return `${format(Number(v)*100)}%`}
function bonusText(v){if(!v)return '无';const names={attack:'攻击',defense:'防御',hp:'生命',speed:'速度',exp:'经验',gold:'金币',fate:'命运',maxHp:'最大生命',heal:'恢复生命',damage:'生命损失',spiritPower:'魂力',count:'数量',name:'道具',type:'类型',value:'效果'};return Object.entries(v).map(([k,n])=>`${names[k]||k} ${typeof n==='object'?bonusText(n):typeof n==='number'?format(n):n}`).join('，')||'无额外加成'}
function resultText(r){return bonusText(Object.fromEntries(Object.entries(r||{}).filter(([k])=>!['text','battle'].includes(k))))}
function select(id,scroll=true){active.value=id;if(scroll)explorer.value?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
function downloadCsv(){const extra=[...Object.entries(presets).flatMap(([k,p])=>[['战斗',difficultyNames[k],'目标出手',p.rounds,'次','battle-core.ENCOUNTER_PRESETS'],['战斗',difficultyNames[k],'生命损耗参数',p.loss,'比例','生成参数，非胜率']]),...elementKeys.flatMap(a=>elementKeys.map(b=>['元素',`${elements[a]}→${elements[b]}`,'伤害倍率',multiplier(a,b),'倍率','battle-core.elementMultiplier'])),...runtimeReport.samples.flatMap(s=>s.checkpoints.flatMap((c,i)=>['level','exp','gold','rings','storyMilestones','eventCount'].map(k=>['运行样本',`${s.sample} / ${s.seed} / 检查点${i+1}`,k,c[k],({level:'等级',exp:'经验',gold:'金币',rings:'枚',storyMilestones:'段',eventCount:'行动次数'})[k],'固定种子合成运行，非玩家统计；lifecycle-runtime.test.js']))),...repairComparison.rows.flatMap(r=>['beforeGold','afterGold','beforeActions','afterActions'].map(k=>['修复样本',`${r.name} / ${r.seed}`,k,r[k],k.endsWith('Gold')?'金币':'行动次数',repairComparison.method])),...fixes.map(f=>['修复',f.title,'前后证据',`${f.before} → ${f.after}`,'文字',f.proof]),...FEATURE_COVERAGE.map(r=>['功能覆盖',r[0],r[1],r[2],'状态',r[3]])].map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF',exportLifecycleCsv(),'\r\n',extra],{type:'text/csv;charset=utf-8;'}));const link=document.createElement('a');link.href=url;link.download='斗罗大陆-全生命周期数值分析.csv';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
